export const RELEASES=[{"version": "1.9.1", "date": "2 Kasım 2026", "title": "Gerçek fotoğraflarla genişleyen ücretsiz skin galerisi", "items": ["Galeri 34 skine çıktı. Beşiktaş, Galatasaray ve Fenerbahçe formalı futbolcu fotoğrafları eklendi.", "Kadın moda, erkek portre ve fitness fotoğrafları ücretsiz seçilebilir.", "Görseller oyuna uygun WebP boyutuna getirildi. Mevcut skin kodları korundu; özel yükleme ücreti 10.000 Gold ve sınırı 2 MB."]},{version:'1.9.0',date:'2 Kasım 2026',title:'Panel yetkileri ve yeni ücretsiz skin galerisi',items:['Hesap sahibi hesap no veya e-posta ile seçtiği panel yetkilerini verir ve geri alır. Her işlem sunucuda ayrı yetki kontrolünden geçer.','Eski emoji skinler yerine yeni karakter görselleri geldi. Galeri skinleri ücretsiz, özel görsel yükleme 10.000 Gold oldu.','A tuşu 10 Gold karşılığında 50 skor verir; S tuşu 100 Gold karşılığında 250 skor vermeye devam eder.','Gold harcaması hücrenin yanında eksi işaretiyle gösterilir. Dikenler ana dikenden çıkarak fırlar; 25 parçadayken diken yiyerek skor toplanabilir.']},{version:'1.8.0',date:'2 Kasım 2026',title:'Sohbet ücretleri, takım renkleri ve oyuncu takibi',items:['Haykır tüm odalara 50.000 Gold karşılığında mavi mesaj gönderir. Yetersiz bakiyede mesaj gönderilmez.','Klan sohbetini yalnızca aynı odadaki klan üyeleri görür. Takım sarı, klan turkuaz; ikisinde de olanlarda takım önceliklidir.','Sıralamada kendi ismin kırmızı, takım sarı, klan turkuaz ve diğerleri beyazdır. Hücre isim ve skorları da ilişki rengine uyar.','Kamera oyuncuyu takip eder; yön kilidi yalnızca küçük noktayla gösterilir. Harcanan Gold eksi işaretiyle görünür.','Yemle çoğalan diken, yem yönünde fırlatılır; hareketi yumuşatılır. 80 taban ve 800 toplam diken sınırı korunur.']},{version:'1.7.0',date:'2 Kasım 2026',title:'Mobil sohbet, MMA-1 ve oyun dengesi',items:['Mobil sohbet küçük simgeyle açılır; menü taşmaları ve GM paneli kaydırması düzeltildi.','MMA-1: hesaba özel 80 milyon oda Gold’u, her 5 saatte yeniden dolar ve diğer odalara taşınmaz.','Hücre hareketi yavaşlatıldı; doğal ve atılan yemler 10 skor verir.','Başlangıçta 80 diken vardır. Yedi yemle boş alana yeni diken çıkar; oda sınırı 800’dür.','Fare tekerleğiyle yakınlaştırma Etrafı Göster açıkken de çalışır; masaüstü menü düğmesi gizlendi.']},{version:'1.6.0',date:'2 Kasım 2026',title:'Oda geçişi, tema ve sohbet düzeltmeleri',items:['Oyundayken farklı odayı seçip Oyna veya İzle ile geçebilirsin. Aynı odada mevcut hücren korunur.','Tekrar yalnızca yutulduktan sonra ve düğmeye basıldığında açılır.','Karanlık, Kenar, Klan ve Etrafı Göster ayarları düzeltildi; kesik hücre halkası kaldırıldı.','Sohbet Haykır, Klan, Takım ve Herkes kanallarına ayrıldı.','Skin yükleme sınırı 2 MB oldu. ZirvePass kapalı: Yakında gelecek.']},{version:'1.5.0',date:'1 Kasım 2026',title:'Sayfam, menü ve GM paneli yenilendi',items:['Ana menü üç sütun, neon oyun çerçevesi ve kompakt kontrollerle yeniden düzenlendi.','Sayfam açık mavi zemine, ortalanmış hesap işlemlerine ve skora göre genişleyen galibiyet kutularına geçti.','GM paneli sol menü, genel bakış, canlı oyuncular, kullanıcılar, odalar, Boost ve ekonomi sayfalarına ayrıldı.','Canlı oyuncu satırından skor ekleme, sohbet yasağı ve oyuncu atma yapılabilir.']},{version:'1.4.0',date:'1 Kasım 2026',title:'Daha kompakt menü ve yeni oda sırası',items:['Masaüstü menüsü ekran yüksekliğine uyarlanır; daha küçük kartlar ve kontroller.','Pin Sorgula menüden kaldırıldı. SPVS-1 ilk sıraya alındı, Boss odası kaldırıldı.','FFA-10’dan sonra Etkinlik-1, Alan-1 ve yeni Alan-2 sıralanır.','Oyun ekranında skor, Gold, sonuç duyuruları ve sağ alt bilgiler yeniden yerleştirildi.']},{version:'1.3.0',date:'1 Kasım 2026',title:'Rekorların son 5 dakikasını izle',items:['Tekrarlar ayrı sekmede açılır; duraklatma, sarma ve hız seçimi vardır.','Onur Tablosu rekor sahibinin turda kullandığı skini gösterir.','Sayfam kupa kartı, Gold/Bonus satırları ve renkli galibiyet kutularıyla yenilendi.','ZirvePass fiyatı 5.000.000 Gold oldu.']}];
export function releaseNews({esc}){const r=RELEASES[0];return `<b>${esc(r.title)}</b><p>Sürüm ${esc(r.version)} · ${esc(r.date)}</p><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button data-page="updates">Tüm güncelleme notları →</button>`}
export function releaseHistory({esc}){return `<div class="doc"><h2>Son Güncellemeler</h2>${RELEASES.map(r=>`<section class="sub-card"><small>${esc(r.date)} · ${esc(r.version)}</small><h3>${esc(r.title)}</h3><ul>${r.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div>`}
